\title{Residue-Class Monotonicity of the Minimal Modulus of Sums of Fifth Roots of Unity}
\author{Aristotle}
\date{2026-07-04}

\begin{document}

\begin{abstract}
Let $\zt = e^{2\pi i/5}$ be the standard primitive fifth root of unity. For a
natural number $n$, define $\sigma_5(n)$ to be the infimum of
$\bigl|\sum_{j=1}^n \zt^{c_j}\bigr|$ over all choices of exponents
$c_1,\dots,c_n \in \N$; equivalently, $\sigma_5(n)$ is the least modulus of a
nonnegative integer combination $\sum_{r=0}^4 a_r \zt^r$ with $\sum_r a_r = n$.
We prove that for every residue $r \in \{0,1,2,3,4\}$ the sequence
$k \mapsto \sigma_5(5k+r)$ is non-increasing:
$\sigma_5(5(k+1)+r) \le \sigma_5(5k+r)$ for all $k \in \N$. The proof rests on
the single identity $1 + \zt + \zt^2 + \zt^3 + \zt^4 = 0$, which permits
appending a complete, value-preserving block of five roots to any configuration,
nesting the feasible sets and forcing monotonicity of infima. We locate the exact
values in the golden field $\Q(\sqrt5) \subset \Q(\zt)$, describe the eventual
plateaus of each class, give a closest-vector reformulation, and record the
general statement for $m$-th roots of unity.
\end{abstract}

\maketitle

\section{Introduction}

Sums of roots of unity, $\sum_j \zt^{c_j}$ for $\zt$ a root of unity, permeate
mathematics: they are the characters of finite cyclic groups, the kernels of the
discrete Fourier transform, and, through Gauss and Jacobi sums, central to number
theory. A recurring question is one of \emph{cancellation}: how small can such a
sum be, and what algebraic constraints govern the smallest attainable modulus?
This paper studies the cleanest one-parameter instance for the fifth roots of
unity and proves a monotonicity law along residue classes.

Fix $\zt = e^{2\pi i/5}$, so $\zt^5 = 1$ and the powers
$1, \zt, \zt^2, \zt^3, \zt^4$ are the vertices of a regular pentagon on the unit
circle. Given a budget of $n$ summands, we ask how close to $0$ a sum of $n$ such
powers can be. The resulting quantity $\sigma_5(n)$ is a discrete optimization
value, and our main theorem shows it behaves monotonically once the domain is
stratified by residue modulo $5$.

The engine of the argument is elementary but decisive: the five roots sum to zero.
This lets us pad any configuration by a full balanced block of five roots without
changing its value, so the feasible set of moduli only grows as the budget
increases by five, and the infimum can only decrease. The mechanism uses nothing
about $5$ beyond the vanishing of the complete root sum, so the development
generalizes verbatim to the $m$-th roots of unity.

\section{Definitions and basic properties}

Throughout, $\N = \{0,1,2,\dots\}$ and $\zt = e^{2\pi i/5} \in \C$.

\begin{definition}
Let $\zt = e^{2\pi i/5} = \cos\tfrac{2\pi}{5} + i\sin\tfrac{2\pi}{5}$.
\end{definition}

\begin{proposition}[Order five]
$\zt$ is a primitive fifth root of unity; in particular $\zt^5 = 1$ and
$\zt^j \ne 1$ for $1 \le j \le 4$.
\end{proposition}

\begin{proof}
Immediate from $\zt^5 = e^{2\pi i} = 1$, and $e^{2\pi i j/5} = 1$ forces
$5 \mid j$.
\end{proof}

\begin{proposition}[Complete root sum vanishes]\label{prop:sum}
$\displaystyle \sum_{i=0}^{4} \zt^i = 0.$
\end{proposition}

\begin{proof}
Since $\zt \ne 1$ and $\zt^5 = 1$, the geometric sum gives
$\sum_{i=0}^4 \zt^i = \frac{\zt^5 - 1}{\zt - 1} = 0$. Equivalently, $\zt$ is a
root of the fifth cyclotomic polynomial $x^4 + x^3 + x^2 + x + 1$.
\end{proof}

\begin{proposition}[Order-five exponent reduction]\label{prop:mod}
For every $n \in \N$, $\ \zt^n = \zt^{\,n \bmod 5}.$
\end{proposition}

\begin{proof}
Write $n = 5q + (n \bmod 5)$. Then
$\zt^n = (\zt^5)^q\, \zt^{\,n\bmod 5} = \zt^{\,n\bmod 5}$.
\end{proof}

Proposition~\ref{prop:mod} is the multiplicative order-$5$ analogue, for powers of
$\zt$, of the additive congruence $a^5 \equiv a \pmod 5$. Any sum
$\sum_{j=1}^n \zt^{c_j}$ therefore depends only on the residues $c_j \bmod 5$ and
equals a canonical form $\sum_{r=0}^4 a_r \zt^r$ with $a_r \in \N$,
$\sum_r a_r = n$.

\begin{definition}[Feasible modulus set]
For $n \in \N$,
\[
  \Aset(n) = \Bigl\{\, \bigl|\textstyle\sum_{j=1}^{n} \zt^{c_j}\bigr| : c \colon \{1,\dots,n\} \to \N \,\Bigr\} \subseteq \R_{\ge 0}.
\]
\end{definition}

\begin{definition}[Minimal modulus]
The minimal modulus of a sum of $n$ fifth roots of unity is
$\sigma_5(n) = \inf \Aset(n).$
\end{definition}

\begin{lemma}[Well-posedness]
For every $n$: (1) every element of $\Aset(n)$ is $\ge 0$; (2) $\Aset(n)$ is
bounded below by $0$; (3) $\Aset(n)$ is nonempty; (4) $\sigma_5(n)$ exists and
$\sigma_5(n) \ge 0$.
\end{lemma}

\begin{proof}
(1) Moduli are nonnegative. (2) follows. (3) Take all exponents $0$, giving
$n \in \Aset(n)$. (4) The infimum of a nonempty set bounded below exists and is
$\ge 0$.
\end{proof}

Because $\Aset(n)$ is determined by the finitely many canonical forms, it is
finite and the infimum is attained: $\sigma_5(n) = \min \Aset(n)$.

\begin{example}
$\sigma_5(0) = 0$, $\sigma_5(1) = 1$. For $n = 2$, $|1 + \zt^2| =
2\cos\tfrac{2\pi}{5} = \tfrac{\sqrt5-1}{2} = \varphi^{-1}$ is minimal, so
$\sigma_5(2) = \varphi^{-1} \approx 0.618034$, where $\varphi = \tfrac{1+\sqrt5}{2}$.
\end{example}

\section{One-step monotonicity}

\begin{theorem}[One-step monotonicity]\label{thm:step}
For every $n \in \N$, $\ \sigma_5(n + 5) \le \sigma_5(n).$
\end{theorem}

\begin{proof}
It suffices to show $\Aset(n) \subseteq \Aset(n+5)$; the inequality of infima then
follows. Let $d \in \Aset(n)$ with $d = |S|$, $S = \sum_{j=1}^n \zt^{c_j}$. Define
$c' \colon \{1,\dots,n+5\} \to \N$ by $c'_j = c_j$ for $j \le n$ and
$c'_{n+1+i} = i$ for $0 \le i \le 4$. By Proposition~\ref{prop:sum},
\[
  \sum_{j=1}^{n+5} \zt^{c'_j} = S + \sum_{i=0}^{4}\zt^i = S + 0 = S,
\]
so $d = |S| \in \Aset(n+5)$. As $d$ was arbitrary, $\Aset(n) \subseteq \Aset(n+5)$.
\end{proof}

The appended block $\{0,1,2,3,4\}$ is value-preserving precisely because the
complete set of roots sums to zero.

\section{Residue-class monotonicity}

Every $n$ is uniquely $n = 5k + r$ with $r \in \{0,1,2,3,4\}$, $k \in \N$.

\begin{theorem}[Residue single step]\label{thm:res-step}
For all $r, k \in \N$, $\ \sigma_5(5(k+1)+r) \le \sigma_5(5k + r).$
\end{theorem}

\begin{proof}
$5(k+1)+r = (5k+r)+5$, so this is Theorem~\ref{thm:step} at $n = 5k+r$.
\end{proof}

\begin{theorem}[Residue-class monotonicity]
For each fixed $r \in \{0,1,2,3,4\}$, the sequence $k \mapsto \sigma_5(5k+r)$ is
non-increasing on $\N$.
\end{theorem}

\begin{proof}
A sequence is non-increasing iff $f(k+1) \le f(k)$ for all $k$, which is exactly
Theorem~\ref{thm:res-step} with $f(k) = \sigma_5(5k+r)$.
\end{proof}

\begin{corollary}[Convergence of each class]
For each $r$, $k \mapsto \sigma_5(5k+r)$ is non-increasing and bounded below by
$0$, hence converges to a limit $L_r \ge 0$.
\end{corollary}

\begin{remark}
For $r = 0$, $\sigma_5(5k) = 0$ for all $k$: $k$ complete balanced blocks give
$0 \in \Aset(5k)$, so $\sigma_5(5k) = 0$ and $L_0 = 0$.
\end{remark}

\section{Exact values, plateaus, and the golden field}

The nonzero values of $\sigma_5$ are algebraic integers of $\Q(\zt)$ lying in the
real subfield $\Q(\zt) \cap \R = \Q(\sqrt5)$, since
$|\sum_r a_r \zt^r|^2$ is an integer combination of
$\zt^s + \zt^{-s} = 2\cos\tfrac{2\pi s}{5}$, with
$2\cos\tfrac{2\pi}{5} = \varphi^{-1}$ and $2\cos\tfrac{4\pi}{5} = -\varphi$.

\begin{center}
\begin{tabular}{c|cccc}
$r \backslash k$ & $k=0$ & $k=1$ & $k=2$ & $k=3$ \\
\hline
$0$ & $0$ & $0$ & $0$ & $0$ \\
$1$ & $1$ & $\varphi^{-2}\!\approx\!0.381966$ & $\varphi^{-4}\!\approx\!0.145898$ & --- \\
$2$ & $\varphi^{-1}\!\approx\!0.618034$ & $\sqrt5-2\!\approx\!0.236068$ & $\sqrt5-2\!\approx\!0.236068$ & --- \\
$3$ & $\varphi^{-1}\!\approx\!0.618034$ & $\sqrt5-2\!\approx\!0.236068$ & $\sqrt5-2\!\approx\!0.236068$ & --- \\
$4$ & $\varphi^{-2}\!\approx\!0.381966$ & $\varphi^{-2}\!\approx\!0.381966$ & $\varphi^{-4}\!\approx\!0.145898$ & --- \\
\end{tabular}
\end{center}

Every row is non-increasing. The recurring constants
$\varphi^{-1} = \tfrac{\sqrt5-1}{2}$, $\varphi^{-2} = \tfrac{3-\sqrt5}{2}$,
$\sqrt5 - 2$, and $\varphi^{-4} = \tfrac{7-3\sqrt5}{2}$ all lie in $\Q(\sqrt5)$.

Balanced blocks are free, so any configuration may be reduced by subtracting
$(1,1,1,1,1)$ until $\min_r a_r = 0$, and there are finitely many reduced forms of
bounded total.

\begin{proposition}[Eventual plateau]
For each $r$ there is an index $k_r$ with $\sigma_5(5k+r) = L_r$ for all
$k \ge k_r$.
\end{proposition}

\begin{proof}[Proof sketch]
$L_r$ is the least modulus over reduced canonical forms of total $\equiv r
\pmod 5$; let a minimizer have total $T_r$. Once $5k+r \ge T_r$ (and both are
$\equiv r$), realize the minimizer and pad with balanced blocks to attain $L_r$;
combined with $\sigma_5 \ge L_r$, equality holds.
\end{proof}

In the table, classes $r = 2, 3$ plateau at $\sqrt5 - 2$ from $k = 1$.

\section{Lattice reformulation}

Integer combinations of powers of $\zt$, embedded in $\C$, project onto a rank-$2$
lattice after quotienting by $\sum_i \zt^i = 0$. A configuration
$(a_0,\dots,a_4)$ maps to $\sum_r a_r \zt^r$; the residue $n \equiv r \pmod 5$
selects a coset; and $\sigma_5(n)$ is the distance from the origin to the nearest
attainable lattice point in that coset --- a closest-vector quantity. Increasing
$n$ by $5$ enlarges the coefficient box and shrinks the nearest distance, which is
the geometric content of Theorem~\ref{thm:step}.

\section{Algorithms}

\textbf{Exhaustive canonical-form search.} Enumerate the $\binom{n+4}{4} = O(n^4)$
compositions $(a_0,\dots,a_4)$ of $n$ and minimize $|\sum_r a_r \zt^r|$.

\medskip
\noindent\textbf{Reduced-form search.} Since balanced blocks are free, search only
reduced forms with $\min_r a_r = 0$, total $\le n$ and $\equiv n \pmod 5$; for
fixed residue this exposes the plateau value $L_r$ in constant work.

\section{Applications and future work}

The powers of $\zt$ are the values of the nontrivial characters of $\Z/5\Z$; the
minimal modulus $\sigma_5(n)$ measures maximal cancellation of a budget of $n$
character values, relevant to low-correlation sequence design and exponential-sum
bounds, and connected through Gauss sums to cyclotomic number theory. The
closest-vector reformulation places $\sigma_5$ within the geometry of numbers.

The only property of $5$ used is Proposition~\ref{prop:sum}. Hence for any
$m \ge 2$, with $\omega = e^{2\pi i/m}$ and $\sigma_m(n)$ the minimal modulus of a
sum of $n$ powers of $\omega$, the same padding argument gives
$\sigma_m(n+m) \le \sigma_m(n)$ and residue-class monotonicity modulo $m$.
Determining closed forms for the limits $L_r$, the stabilization indices $k_r$,
and efficient lattice algorithms for $\sigma_m(n)$ are natural next steps.

\section{Conclusion}

We proved that the minimal modulus of a sum of fifth roots of unity is
non-increasing along every residue class modulo $5$. The proof reduces to the
vanishing of the complete root sum, which makes any budget increase by five a
free, value-preserving operation and nests the feasible sets. The exact values
inhabit the golden field $\Q(\sqrt5)$, each class converges to an explicit
plateau, and a closest-vector reading connects the picture to lattice geometry.
The argument generalizes without change to the $m$-th roots of unity.

\end{document}

