"""Minimizing configurations and their exact algebraic values.

For each budget n, reports the canonical configuration (a0,...,a4) achieving
sigma5(n) together with its recognition inside the golden field Q(sqrt 5).
"""
from __future__ import annotations
import cmath, math
from typing import Iterator, Tuple

ZETA = cmath.exp(2j * math.pi / 5)
PHI = (1 + math.sqrt(5)) / 2

def compositions(n: int, parts: int) -> Iterator[Tuple[int, ...]]:
    if parts == 1:
        yield (n,); return
    for first in range(n + 1):
        for rest in compositions(n - first, parts - 1):
            yield (first,) + rest

def minimizer(n: int) -> Tuple[float, Tuple[int, ...]]:
    best, arg = math.inf, (n, 0, 0, 0, 0)
    for c in compositions(n, 5):
        v = abs(sum(a * ZETA ** r for r, a in enumerate(c)))
        if v < best:
            best, arg = v, c
    return best, arg

def name(v: float) -> str:
    table = {0.0: "0", 1.0: "1", 1/PHI: "phi^-1", 1/PHI**2: "phi^-2",
             math.sqrt(5)-2: "sqrt5-2", 1/PHI**4: "phi^-4"}
    for t, nm in table.items():
        if abs(v - t) < 1e-9:
            return nm
    return "?"

if __name__ == "__main__":
    for n in range(16):
        v, c = minimizer(n)
        print(f"n={n:2d}  sigma5={v:.6f}  = {name(v):7s}  witness={c}")

"""Detecting the plateau (stabilization index) of each residue class.

Each class k -> sigma5(5k+r) is non-increasing and eventually constant at a limit
L_r.  This locates the first index k_r at which the class reaches L_r.
"""
from __future__ import annotations
import cmath, math
from typing import Iterator, Tuple, List

ZETA = cmath.exp(2j * math.pi / 5)

def compositions(n: int, parts: int) -> Iterator[Tuple[int, ...]]:
    if parts == 1:
        yield (n,); return
    for first in range(n + 1):
        for rest in compositions(n - first, parts - 1):
            yield (first,) + rest

def sigma5(n: int) -> float:
    return min(abs(sum(a * ZETA ** r for r, a in enumerate(c)))
               for c in compositions(n, 5))

def stabilization(r: int, kmax: int = 6) -> None:
    vals: List[float] = [sigma5(5 * k + r) for k in range(kmax + 1)]
    limit = vals[-1]
    k_r = next(k for k, v in enumerate(vals) if abs(v - limit) < 1e-9)
    seq = "  ".join(f"{v:.6f}" for v in vals)
    print(f"r={r}: {seq}   L_r={limit:.6f}  stabilizes at k_r={k_r}")

if __name__ == "__main__":
    for r in range(5):
        stabilization(r)

"""General modulus m: minimal modulus of a sum of n m-th roots of unity.

Demonstrates that residue-class monotonicity sigma_m(n+m) <= sigma_m(n) holds for
every m >= 2, using the same complete-root-sum-vanishing mechanism.
"""
from __future__ import annotations
import cmath, math
from typing import Iterator, Tuple

def compositions(n: int, parts: int) -> Iterator[Tuple[int, ...]]:
    if parts == 1:
        yield (n,); return
    for first in range(n + 1):
        for rest in compositions(n - first, parts - 1):
            yield (first,) + rest

def sigma_m(n: int, m: int) -> float:
    w = cmath.exp(2j * math.pi / m)
    return min(abs(sum(a * w ** r for r, a in enumerate(c)))
               for c in compositions(n, m))

if __name__ == "__main__":
    for m in (2, 3, 4, 5, 6):
        ok = all(sigma_m(n + m, m) <= sigma_m(n, m) + 1e-12 for n in range(0, 12))
        row = [round(sigma_m(n, m), 4) for n in range(0, m + 6)]
        print(f"m={m}: sigma_m(0..{m+5}) = {row}   monotone-by-{m}: {ok}")

